def changed_paths(before, after):
    """Return sorted dot-separated paths for additions, removals, or unequal leaves.

    Recurses only where BOTH values are dictionaries; treats lists atomically.
    If an entire dictionary key is added/removed, returns that parent path only.
    """
    paths = set()
    _diff(before, after, "", paths)
    return sorted(paths)


def _diff(before, after, prefix, paths):
    for key in set(before.keys()) | set(after.keys()):
        path = f"{prefix}.{key}" if prefix else key
        if key not in before:
            paths.add(path)
        elif key not in after:
            paths.add(path)
        else:
            b_val = before[key]
            a_val = after[key]
            if isinstance(b_val, dict) and isinstance(a_val, dict):
                _diff(b_val, a_val, path, paths)
            elif b_val != a_val:
                paths.add(path)
