from bisect import bisect_right

def histogram(edges, values):
    if not hasattr(edges, '__len__') or len(edges) < 2:
        raise ValueError("edges must have at least two elements")
    for i in range(len(edges) - 1):
        if edges[i] >= edges[i + 1]:
            raise ValueError("edges must be strictly increasing")

    n_bins = len(edges) - 1
    counts = [0] * n_bins
    lo = edges[0]
    hi = edges[-1]

    for v in values:
        if v < lo or v > hi:
            continue
        idx = bisect_right(edges, v) - 1
        if idx > n_bins - 1:
            idx = n_bins - 1
        counts[idx] += 1

    return counts
```

