import copy


def merge(base, overlay):
    """Recursively merge two JSON-like dictionaries into a deep-independent result.

    - Overlay values replace base values (including lists and None).
    - A None value does not delete a key.
    - Inputs are not mutated and are not aliased in the result.
    """
    if isinstance(base, dict) and isinstance(overlay, dict):
        result = {}
        for key in base:
            if key in overlay:
                result[key] = merge(base[key], overlay[key])
            else:
                result[key] = copy.deepcopy(base[key])
        for key in overlay:
            if key not in base:
                result[key] = copy.deepcopy(overlay[key])
        return result
    else:
        return copy.deepcopy(overlay)
```

