def pack(items, max_bytes):
    if max_bytes < 1:
        raise ValueError("max_bytes must be >= 1")

    for i, s in enumerate(items):
        if len(s.encode('utf-8')) > max_bytes:
            raise ValueError(f"Item {i} exceeds max_bytes")

    if not items:
        return []

    result = []
    current = []
    current_sum = 0

    for s in items:
        blen = len(s.encode('utf-8'))
        if current_sum + blen <= max_bytes:
            current.append(s)
            current_sum += blen
        else:
            result.append(current)
            current = [s]
            current_sum = blen

    result.append(current)
    return result
