import heapq


def order(deps):
    # Collect all nodes (keys and prerequisite-only nodes)
    all_nodes = set(deps.keys())
    for prereqs in deps.values():
        for p in prereqs:
            all_nodes.add(p)

    # Build prerequisite sets and reverse (dependent) mapping
    prereq_map = {}
    dependents = {node: [] for node in all_nodes}
    for node in all_nodes:
        prereqs = set(deps.get(node, []))
        prereq_map[node] = prereqs
        for p in prereqs:
            dependents[p].append(node)

    # Track how many prerequisites each node still needs
    remaining = {node: len(prereq_map[node]) for node in all_nodes}

    # Seed the min-heap with nodes that have no prerequisites
    heap = []
    for node in all_nodes:
        if remaining[node] == 0:
            heapq.heappush(heap, node)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dep in dependents[node]:
            remaining[dep] -= 1
            if remaining[dep] == 0:
                heapq.heappush(heap, dep)

    if len(result) != len(all_nodes):
        raise ValueError("cycle detected")

    return result
